const VERSION='slovoboy-levels-109-v1';
const FILES=['./','index.html','app.js?v=109','engine.js?v=109','progression.js?v=109','style.css?v=109','icon.svg?v=109','icon-192.png?v=109','icon-512.png?v=109','manifest.webmanifest?v=109','app.js','engine.js','progression.js','fonts/Manrope-variable.ttf','style.css','words.json','icon.svg','icon-192.png','icon-512.png','manifest.webmanifest',...['select','place','remove','error','draw','exchange','dealer','start','hit','bot_hit','round','win','lose'].map(n=>'sounds/snd_'+n+'.wav')];
self.addEventListener('install',e=>{e.waitUntil(caches.open(VERSION).then(c=>c.addAll(FILES)));self.skipWaiting()});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==VERSION).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(fetch(e.request).then(r=>{if(r.ok){let copy=r.clone();caches.open(VERSION).then(c=>c.put(e.request,copy))}return r}).catch(()=>caches.match(e.request).then(r=>r||(e.request.mode==='navigate'?caches.match('index.html'):Response.error()))))});
